"""Daemon JSON configuration with backup and atomic replacement."""

import json
import os
import tempfile
from collections.abc import Mapping
from pathlib import Path


def _backup_path(path):
    """Return the backup path that sits next to *path*."""
    return Path(path).with_name(Path(path).name + ".bak")


def _parse_config(text):
    """Parse *text* as JSON, requiring a JSON object (mapping)."""
    value = json.loads(text)
    if not isinstance(value, Mapping):
        raise ValueError("configuration must be a JSON object")
    return value


def _atomic_write_text(path, text):
    """Write *text* to *path* atomically (temp file + os.replace)."""
    path = Path(path)
    fd, tmp_name = tempfile.mkstemp(
        dir=str(path.parent), prefix="." + path.name + ".", suffix=".tmp"
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_name, path)
    except BaseException:
        try:
            os.unlink(tmp_name)
        except FileNotFoundError:
            pass
        raise


def write_config(path, data):
    """Persist *data* to *path*.

    The mapping is fully validated and serialized before any file is touched.
    The previous valid configuration is preserved as ``<name>.bak`` and the
    live file is replaced atomically so a crash can never leave it corrupt.
    """
    if not isinstance(data, Mapping):
        raise TypeError("configuration data must be a mapping")

    # Serialize first so validation errors never modify the filesystem.
    # allow_nan=False keeps the output valid, standards-compliant JSON.
    serialized = json.dumps(data, allow_nan=False)

    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)

    if path.exists():
        try:
            existing = path.read_text(encoding="utf-8")
            _parse_config(existing)
        except (OSError, ValueError):
            # The live file is missing/corrupt: keep any existing good backup.
            pass
        else:
            # Preserve the previous *valid* configuration as the backup.
            _atomic_write_text(_backup_path(path), existing)

    _atomic_write_text(path, serialized)


def read_config(path):
    """Read the configuration from *path*.

    If the live file is missing or corrupt, fall back to a valid backup. If
    neither copy is usable, raise an error.
    """
    path = Path(path)
    backup = _backup_path(path)

    live_error = None
    try:
        return _parse_config(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        live_error = exc

    backup_error = None
    try:
        return _parse_config(backup.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        backup_error = exc

    if isinstance(live_error, FileNotFoundError) and isinstance(
        backup_error, FileNotFoundError
    ):
        raise FileNotFoundError(
            "no configuration file found at {!s} or its backup".format(path)
        )

    raise ValueError(
        "no valid configuration at {!s} (backup also unusable)".format(path)
    ) from live_error

